def main():
    device = "cuda" if torch.cuda.is_available() else "cpu"
    print("Device:", device, flush=True)

    import subprocess, sys
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "vegaml"], check=True)
    import vegaml
    print("Loading vegaml...", flush=True)
    v = vegaml.load()
    print("vegaml", vegaml.__version__, flush=True)

    import io
    def load_split(name):
        raw = {"fit": _FIT_JSONL, "val": _VAL_JSONL, "test": _TEST_JSONL}[name]
        return [json.loads(line) for line in io.StringIO(raw) if line.strip()]
    fit_rows, val_rows, test_rows = load_split("fit"), load_split("val"), load_split("test")
    print("Loaded fit=%d val=%d test=%d" % (len(fit_rows), len(val_rows), len(test_rows)), flush=True)

    print("Fitting vegaml policy...", flush=True)
    t0 = time.time()
    policy = vegaml.fit_policy(v, fit_rows, TOOLUSE_QUESTIONS)
    print("Policy fitted in %.1fs" % (time.time() - t0), flush=True)

    def policy_acc(rows):
        ok = 0
        for r in rows:
            out = policy.decide(r["state"])
            a = out["answers"]
            nt = a["next_tool"]
            pred_nt = max(nt["probs"], key=nt["probs"].get) if nt.get("probs") else nt.get("value")
            pr = a["run_precheck"]
            p_true = pr["probability"] if "probability" in pr else pr["probs"].get("true", 0.5)
            pred_pr = p_true >= 0.5
            if str(pred_nt).lower() == str(r["gold"]["next_tool"]).lower() and pred_pr == bool(r["gold"]["run_precheck"]):
                ok += 1
        return ok / len(rows) if rows else 0.0

    val_acc = policy_acc(val_rows)
    print("Teacher val accuracy (both questions): %.1f%%" % (val_acc * 100), flush=True)

    print("Loading student %s..." % MODEL_NAME, flush=True)
    from transformers import AutoModelForCausalLM, AutoTokenizer
    student = AutoModelForCausalLM.from_pretrained(MODEL_NAME, torch_dtype=torch.bfloat16, device_map="auto")
    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)
    print("Student: %d params" % sum(p.numel() for p in student.parameters()), flush=True)

    down_proj = student.model.layers[LAYER].mlp.down_proj
    print("Target: layer %d down_proj %s" % (LAYER, down_proj.weight.shape), flush=True)

    # Option token ids: first token of each criterion / yes / no
    crit_ids = {c: tokenizer(c).input_ids[0] for c in CRITERIA}
    yes_id = tokenizer("yes").input_ids[0]
    no_id = tokenizer("no").input_ids[0]
    print("crit_ids:", crit_ids, "yes:", yes_id, "no:", no_id, flush=True)

    def encode(rows_list):
        return [tokenizer(tooluse_prompt(r["state"]), return_tensors="pt").input_ids.shape[1] - 1
                for r in rows_list]

    train_encs, val_encs, test_encs = encode(fit_rows), encode(val_rows), encode(test_rows)

    # Teacher targets: for each row, scalar gap = logit(gold) - max logit(non-gold),
    # summed over next_tool (6-way) and run_precheck (yes/no).
    teacher_targets: List[float] = []
    for r in fit_rows:
        out = policy.decide(r["state"])
        a = out["answers"]
        nt = a["next_tool"]
        probs = nt.get("probs") or {}
        gold_nt = str(r["gold"]["next_tool"]).lower()
        p_gold = max(probs.get(gold_nt, probs.get(str(r["gold"]["next_tool"]), 1e-7)), 1e-7)
        p_rest = max((v for k, v in probs.items() if k.lower() != gold_nt), default=1e-7)
        gap_nt = math.log(p_gold / max(p_rest, 1e-7))
        pr = a["run_precheck"]
        p_yes = pr.get("probability", pr.get("probs", {}).get("true", 0.5))
        gap_pr = math.log(max(p_yes, 1e-7) / max(1 - p_yes, 1e-7)) if bool(r["gold"]["run_precheck"]) \
            else math.log(max(1 - p_yes, 1e-7) / max(p_yes, 1e-7))
        teacher_targets.append(gap_nt + gap_pr)
    teacher_targets = torch.tensor(teacher_targets, dtype=torch.float32, device=student.device)

    def student_gap(tokens, enc, gold_nt, gold_pr):
        with torch.no_grad():
            out = student(input_ids=tokens, use_cache=False)
            logits = out.logits[0, enc, :]
        gold_id = crit_ids[str(gold_nt).lower()]
        other_ids = [tid for c, tid in crit_ids.items() if c != str(gold_nt).lower()]
        gap_nt = logits[gold_id].item() - max(logits[t].item() for t in other_ids)
        gap_pr = logits[yes_id].item() - logits[no_id].item()
        if not gold_pr:
            gap_pr = -gap_pr
        return gap_nt + gap_pr

    print("Extracting keys...", flush=True)
    keys = []
    for r, enc in zip(fit_rows, train_encs):
        tokens = tokenizer(tooluse_prompt(r["state"]), return_tensors="pt").input_ids.to(student.device)
        kt = [None]
        h = down_proj.register_forward_pre_hook(lambda m, inp: kt.__setitem__(0, inp[0]))
        with torch.no_grad():
            student(input_ids=tokens, use_cache=False)
        h.remove()
        keys.append(kt[0][0, enc, :].cpu() if kt[0] is not None else torch.zeros(down_proj.in_features))
    K = torch.stack(keys).to(student.device).float()
    print("Keys:", K.shape, flush=True)

    print("Reading student gaps...", flush=True)
    sg = []
    for r, enc in zip(fit_rows, train_encs):
        tokens = tokenizer(tooluse_prompt(r["state"]), return_tensors="pt").input_ids.to(student.device)
        sg.append(student_gap(tokens, enc, r["gold"]["next_tool"], r["gold"]["run_precheck"]))
    student_gaps = torch.tensor(sg, dtype=torch.float32, device=student.device)

    scale = teacher_targets - student_gaps
    R = K * scale.unsqueeze(1)

    print("Solving...", flush=True)
    best, best_score = None, float("inf")
    original = down_proj.weight.detach().clone()
    for lam in LAMBDAS:
        KtK = K.T @ K
        A = KtK + lam * len(K) * KtK.diagonal().unsqueeze(0) * torch.eye(K.shape[1], device=student.device)
        A = A + 1e-6 * A.diagonal().mean() * torch.eye(K.shape[1], device=student.device)
        t0 = time.time()
        # MEMIT least squares: delta W [out, in] with deltaW @ k_i ~= scale_i.
        # A = K^T K + reg  [in, in];  X = A^-1 K^T  [in, n];  deltaW = scale^T X^T -> [1, in] -> broadcast [out, in]
        X = torch.linalg.solve(A, K.T.float())                       # [3584, 300]
        dW = (scale @ X.T).unsqueeze(0).expand(down_proj.weight.shape[0], -1).contiguous().float()  # [1024, 3584]
        print("  lambda=%s solved in %.0fms" % (lam, (time.time() - t0) * 1000), flush=True)
        for dose in DOSES:
            with torch.no_grad():
                down_proj.weight.data.add_(dW.to(device=down_proj.weight.device, dtype=down_proj.weight.dtype) * dose)
            gap_sum = 0.0
            for r, enc in zip(val_rows, val_encs):
                tokens = tokenizer(tooluse_prompt(r["state"]), return_tensors="pt").input_ids.to(student.device)
                gap_sum += abs(student_gap(tokens, enc, r["gold"]["next_tool"], r["gold"]["run_precheck"]))
            down_proj.weight.data.copy_(original)
            score = gap_sum / len(val_rows)
            if score < best_score:
                best_score, best = score, {"lam": lam, "dose": dose, "dW": dW * dose}
            print("    dose=%.1f val gap=%.4f" % (dose, score), flush=True)

    print("Best: lambda=%s dose=%s" % (best["lam"], best["dose"]), flush=True)
    with torch.no_grad():
        down_proj.weight.data.add_(best["dW"].to(device=down_proj.weight.device, dtype=down_proj.weight.dtype))

    print("\n=== Test accuracy (post-edit) ===", flush=True)
    ok_nt = ok_pr = 0
    for r, enc in zip(test_rows, test_encs):
        tokens = tokenizer(tooluse_prompt(r["state"]), return_tensors="pt").input_ids.to(student.device)
        with torch.no_grad():
            out = student(input_ids=tokens, use_cache=False)
            logits = out.logits[0, enc, :]
        pred_nt = max(crit_ids, key=lambda c: logits[crit_ids[c]].item())
        pred_pr = logits[yes_id].item() > logits[no_id].item()
        if pred_nt == str(r["gold"]["next_tool"]).lower():
            ok_nt += 1
        if pred_pr == bool(r["gold"]["run_precheck"]):
            ok_pr += 1
    n = len(test_rows) or 1
    print("next_tool: %.1f%% (%d/%d)" % (ok_nt / n * 100, ok_nt, len(test_rows)), flush=True)
    print("run_precheck: %.1f%% (%d/%d)" % (ok_pr / n * 100, ok_pr, len(test_rows)), flush=True)

    out_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "out_tooluse")
    os.makedirs(out_dir, exist_ok=True)
    student.save_pretrained(out_dir)
    tokenizer.save_pretrained(out_dir)
    meta = {"model": MODEL_NAME, "layer": LAYER, "width": WIDTH, "lambda": best["lam"], "dose": best["dose"],
            "val_teacher_acc": val_acc, "test_next_tool_acc": ok_nt / n, "test_precheck_acc": ok_pr / n,
            "n_fit": len(fit_rows), "n_val": len(val_rows), "n_test": len(test_rows), "variant": "tooluse_gauntlet"}
    with open(os.path.join(out_dir, "embed_meta.json"), "w") as f:
        json.dump(meta, f, indent=2)
    print("Saved to", out_dir, flush=True)


if __name__ == "__main__":
    main()
